 const pageNames={digest:'原书精读精简版',book:'奥本海姆原书',reference:'公式与方法速查',overview:'学习总览',papers:'历年真题',practice:'专项训练',chapters:'考点地图',notebook:'错题与收藏',resources:'逐题方法',downloads:'资料与安装'};
 function render(){let {page,params}=route();if(!pageNames[page])page='overview';$('#breadcrumb').textContent=pageNames[page];$$('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===page||(page==='book'&&a.dataset.page==='downloads')||(page==='digest'&&a.dataset.page==='overview')));let html=({overview,chapters,downloads,resources,reference,book,digest}[page]||({papers,practice,notebook}[page]))(params);$('#main').innerHTML=html;typeset($('#main'));document.body.classList.toggle('book-reading-active',page==='book');document.body.classList.toggle('large-type',!!state.font);document.body.classList.toggle('dark',!!state.dark);bindFilters(page);}
 function bindFilters(page){if(page==='book')bookUI.bind($('#main'));if(page==='reference'&&$('#reference-search')){const commit=()=>navigate('reference',Object.fromEntries([['category',route().params.get('category')||''],['chapter',$('#reference-chapter').value],['q',$('#reference-search').value]].filter(x=>x[1])));$('#reference-chapter').onchange=commit;$('#reference-search').onchange=commit;$('#reference-search').onkeydown=e=>{if(e.key==='Enter')commit();};}if(page==='resources'&&$('#method-year')){const commit=()=>{expandedLimit=60;navigate('resources',Object.fromEntries([['year',$('#method-year').value],['chapter',$('#method-chapter').value],['q',$('#method-search').value]].filter(x=>x[1])));};$('#method-year').onchange=commit;$('#method-chapter').onchange=commit;$('#method-search').onchange=commit;$('#method-search').onkeydown=e=>{if(e.key==='Enter')commit();};}if(page==='resources'&&$('#resource-chapter')){let commit=()=>navigate('resources',Object.fromEntries([['view',route().params.get('view')||'guides'],['chapter',$('#resource-chapter').value],['platform',$('#resource-platform')?.value||'']].filter(x=>x[1])));$('#resource-chapter').onchange=commit;if($('#resource-platform'))$('#resource-platform').onchange=commit;}if(page==='papers'){let commit=()=>{expandedLimit=60;navigate('papers',Object.fromEntries([['year',$('#paper-year').value],['chapter',$('#paper-chapter').value],['q',$('#paper-search').value]].filter(x=>x[1])));};$('#paper-year').onchange=commit;$('#paper-chapter').onchange=commit;$('#paper-search').onkeydown=e=>{if(e.key==='Enter')commit();};$('#paper-search').onchange=commit;}if(page==='practice'){let commit=()=>navigate('practice',Object.fromEntries([['kind',route().params.get('kind')||'original'],['chapter',$('#practice-chapter').value],['group',$('#practice-group')?.value||'']].filter(x=>x[1])));$('#practice-chapter').onchange=commit;if($('#practice-group'))$('#practice-group').onchange=commit;}}
 function actionButtons(q){let st=state.questions[q.id]||{};return ['done','wrong','star'].map((k,i)=>`<button data-action="mark" data-mark="${k}" class="${st[k]?'selected':''}">${st[k]?['已掌握 ✓','待复盘 ✓','已收藏 ★'][i]:['标记掌握','需要复盘','收藏此题 ☆'][i]}</button>`).join('');}
 function readerActions(q){return `${actionButtons(q)}<details class="reader-support-menu"><summary>学习辅助</summary><div class="reader-support-content"><div class="tags">${tags(q)}</div><button data-action="open-digest" data-chapter="${escape(q.chapters?.[0]||'')}">本章精读提要 ↗</button><button data-action="open-reference" data-chapter="${escape(q.chapters?.[0]||'')}">本章公式与方法 ↗</button>${conceptsFor(q).length?'<button data-action="jump-concepts">教材概念 ↓</button>':''}${examMethodById.has(q.id)||methodsFor(q).length?'<button data-action="jump-question-methods">解法对照 ↓</button>':''}<button data-action="jump-question-notes">复盘笔记 ↓</button></div></details>`;}
 function openQuestion(id,queue){let q=byId.get(id);if(!q)return;current=q;currentQueue=queue?.length?queue:(window.currentFiltered||questions);if(!currentQueue.some(x=>x.id===id))currentQueue=all;currentIndex=currentQueue.findIndex(x=>x.id===id);state.questions[id]={...(state.questions[id]||{}),readAt:Date.now()};save();let st=state.questions[id];$('#reader-position').textContent=(q.training?q.ref:q.year+'年 第'+q.ref+'题')+` · ${currentIndex+1}/${currentQueue.length}`;
  $('#reader-body').innerHTML=`<header class="question-heading"><p class="reader-label">${q.textbook?'奥本海姆第二版 · '+escape(bookExerciseById.get(q.id)?.bookQuestion||q.scope.split(' ')[0]):q.training?q.group+' · 原创训练':q.year+'年真题 · 第'+escape(q.ref)+'题'}</p><h1 class="reader-title">${escape(q.title)}</h1></header><div class="reader-study-layout"><section class="lesson">${renderQuestionOriginal(q)}${renderParaphrase(q)}<section class="question-main-solution" id="question-solution"><h2>详细解析</h2><div class="step-box"><strong>第一步，为什么这样想</strong>${md(q.firstStep||'先明确所给条件、输入的定义域和需要判断的性质，再选择时域或变换域。')}</div>${md(q.solution)}${renderFigures(q)}<div class="answer-box"><strong>关键结果</strong>${md(q.answer||'见上方推导。')}</div>${q.pitfalls?.length?`<div class="question-pitfalls"><h3>易错点与检查</h3><ul>${q.pitfalls.map(x=>`<li>${md(x)}</li>`).join('')}</ul></div>`:''}</section><div class="question-review-tools"><div class="reader-actions">${readerActions(q)}</div><p class="question-encouragement" id="question-encouragement" role="status">${escape(questionEncouragement(q))}</p></div>${renderOtherMethods(q)}${renderTextbookExtras(q)}<details class="question-extra question-note-panel" id="question-notes" ${st.note?'open':''}><summary>我的复盘笔记${st.note?' · 已保存':''}</summary><textarea id="question-note" data-id="${escape(q.id)}" placeholder="记录第一步卡在哪里、哪个条件漏看了…">${escape(st.note||'')}</textarea><p class="source-note">输入后自动保存在本机。</p></details></section></div>`;
  typeset($('#reader-body'));$('#prev-question').disabled=currentIndex===0;$('#next-question').disabled=currentIndex>=currentQueue.length-1;document.body.classList.add('question-open');if(!$('#reader').open)$('#reader').showModal();$('#reader').scrollTop=0;
  $('#question-note').oninput=e=>{let id=e.target.dataset.id;state.questions[id]={...(state.questions[id]||{}),note:e.target.value,updatedAt:Date.now()};clearTimeout(save.timer);save.timer=setTimeout(save,400);};
 }
 function renderFigures(q){return (q.figures||[]).map((f,i)=>{let path=typeof f==='string'?f:f.path||f.file||f.src;let caption=typeof f==='string'?`对应图解 ${i+1}`:f.caption||f.title||`对应图解 ${i+1}`;return path?`<figure class="figure"><img src="assets/${escape(path.replace(/^.*assets\//,''))}" alt="${escape(caption)}" loading="lazy" data-expand><figcaption>${escape(caption)}</figcaption></figure>`:'';}).join('');}
 let viewerScale=1,viewerFits=true;
 function setImageScale(scale,fit=false){const picture=$('#expanded-image'),canvas=$('#image-canvas');if(!picture.naturalWidth)return;const old=picture.getBoundingClientRect().width||1,x=(canvas.scrollLeft+canvas.clientWidth/2)/old;viewerScale=Math.min(4,Math.max(.1,scale));viewerFits=fit;picture.style.width=Math.round(picture.naturalWidth*viewerScale)+'px';picture.style.height='auto';$('#image-zoom-label').textContent=Math.round(viewerScale*100)+'%';if(!fit)canvas.scrollLeft=Math.max(0,x*picture.getBoundingClientRect().width-canvas.clientWidth/2);}
 function fitImage(){const picture=$('#expanded-image');if(picture.naturalWidth)setImageScale(Math.min(1,($('#image-canvas').clientWidth-30)/picture.naturalWidth),true);}
 function openImage(src,caption){const picture=$('#expanded-image');$('#image-caption').textContent=caption;$('#image-dimensions').textContent='载入原图…';picture.alt=caption;picture.onerror=()=>{$('#image-dimensions').textContent='原图暂未加载成功，请关闭后重试。';};picture.onload=()=>{$('#image-dimensions').textContent=`原图 ${picture.naturalWidth} × ${picture.naturalHeight} 像素`;fitImage();$('#image-canvas').scrollTop=0;};picture.style.width='auto';picture.src=src;if(!$('#image-dialog').open)$('#image-dialog').showModal();if(picture.complete&&picture.naturalWidth)picture.onload();}
 $('#image-zoom-in').onclick=()=>setImageScale(viewerScale*1.3);$('#image-zoom-out').onclick=()=>setImageScale(viewerScale/1.3);$('#image-fit').onclick=fitImage;$('#image-native').onclick=()=>setImageScale(1);$('#expanded-image').ondblclick=()=>viewerFits?setImageScale(1):fitImage();window.addEventListener('resize',()=>{if($('#image-dialog').open&&viewerFits)fitImage();});
 function downloadBackup(){let data=JSON.stringify({app:'sysu-signals-study',exportedAt:new Date().toISOString(),state},null,2);if(window.Android?.exportProgress){window.Android.exportProgress(data);return;}let a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type:'application/json'}));a.href=url;a.download='信号研习室_学习记录.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('备份已导出');}
 async function importBackup(file){try{let incoming=JSON.parse(await file.text());if(incoming.app!=='sysu-signals-study'||!incoming.state?.questions)throw Error();let count=0;for(let [id,v]of Object.entries(incoming.state.questions)){if(!byId.has(id)||!v||typeof v!=='object')continue;let local=state.questions[id]||{},localDate=local.updatedAt||local.readAt||0,inDate=v.updatedAt||v.readAt||0;if(inDate>=localDate){state.questions[id]={done:!!v.done,wrong:!!v.wrong,star:!!v.star,note:String(v.note||'').slice(0,50000),readAt:+v.readAt||0,updatedAt:+v.updatedAt||0};count++;}}save();render();toast(`已合并${count}条学习记录`);}catch{toast('无法读取备份，请选择本工具导出的 JSON 文件。');}}
 document.addEventListener('click',e=>{let image=e.target.closest('[data-expand]');if(image){openImage(image.dataset.full||image.src,image.dataset.caption||image.alt||'题目图解');return;}let el=e.target.closest('[data-action]');if(!el)return;let a=el.dataset.action;if(a==='toggle-reference-notes'){const panel=el.closest('.clear-transform-panel'),expanded=el.getAttribute('aria-expanded')!=='true';panel.querySelector('.clear-table-note-body').hidden=!expanded;el.setAttribute('aria-expanded',String(expanded));el.textContent=expanded?'收起符号约定与原表说明 ▴':'完整符号约定与原表说明 ▾';return;}if(a==='toggle-reference-table'){const panel=el.closest('.clear-transform-panel'),expanded=el.getAttribute('aria-expanded')!=='true';panel.querySelectorAll('[data-reference-extra]').forEach(row=>row.hidden=!expanded);el.setAttribute('aria-expanded',String(expanded));el.textContent=expanded?'只看常用 '+el.dataset.core+' 行 ↑':'显示完整对照表（'+el.dataset.total+'行） ↓';return;}if(a==='another-encouragement'){encouragementIndex=(encouragementIndex+1)%encouragements.length;const line=$('#study-encouragement-text');if(line)line.textContent=encouragements[encouragementIndex];}if(a==='open-digest'){if($('#reader').open)$('#reader').close();navigate('digest',el.dataset.chapter?{chapter:el.dataset.chapter}:{});}if(a==='open-book'){if($('#reader').open)$('#reader').close();navigate('book',el.dataset.pdf?{pdf:el.dataset.pdf}:{});}if(a==='open-reference'){if($('#reader').open)$('#reader').close();navigate('reference',{chapter:el.dataset.chapter||''});}if(a==='open-guide'){if($('#reader').open)$('#reader').close();navigate('resources',{guide:el.dataset.guide});}if(a==='open-analysis'){openQuestion(el.dataset.id);revealSection('#question-methods');}if(a==='jump-original-context')revealSection('#question-original-pages');if(a==='jump-concepts')revealSection($('#question-concepts .concept-card')||$('#question-concepts'));if(a==='jump-question-methods')revealSection('#question-methods');if(a==='jump-question-notes')revealSection('#question-notes');if(a==='print-guide')window.print();if(a==='open')openQuestion(el.dataset.id);if(a==='open-method'){openQuestion(el.dataset.id);const detail=$('.method-solution[data-method="'+el.dataset.method+'"]');if(detail)revealSection(detail);}if(a==='jump-methods')$('#method-index-head')?.scrollIntoView({block:'start'});if(a==='go')navigate(el.dataset.page);if(a==='mark'&&current){let id=current.id,k=el.dataset.mark;let st=state.questions[id]||{};st[k]=!st[k];if(k==='done'&&st.done)st.wrong=false;if(k==='wrong'&&st.wrong)st.done=false;st.updatedAt=Date.now();state.questions[id]=st;save();$('.reader-actions').innerHTML=readerActions(current);$('#question-encouragement').textContent=questionEncouragement(current);toast(k==='done'?(st.done?'已标记掌握':'已取消掌握标记'):k==='wrong'?(st.wrong?'已加入待复盘':'已移出待复盘'):(st.star?'已收藏':'已取消收藏'));}if(a==='reset-filter')navigate('papers');if(a==='load-more'){expandedLimit+=60;render();}if(a==='notebook-mode')navigate('notebook',{mode:el.dataset.mode});if(a==='random-training'){randomQueue=[];navigate('practice',{kind:route().params.get('kind')||'original',random:'1'});if(route().params.get('random')==='1')render();}if(a==='export')downloadBackup();if(a==='import')$('#import-progress').click();});
 $('#export-progress').onclick=downloadBackup;$('#import-progress').onchange=e=>{if(e.target.files[0])importBackup(e.target.files[0]);e.target.value='';};
 $('#close-reader').onclick=()=>{$('#reader').close();save();render();};$('#reader').addEventListener('close',()=>{document.body.classList.remove('question-open');save();render();});$('#close-image').onclick=()=>$('#image-dialog').close();$('#prev-question').onclick=()=>openQuestion(currentQueue[currentIndex-1]?.id,currentQueue);$('#next-question').onclick=()=>openQuestion(currentQueue[currentIndex+1]?.id,currentQueue);$('#print-question').onclick=()=>window.print();
